service.method:

INSERT INTO SBMMA
(
	  MODULE
	, DESCRIPTION
	, PARENT
	, SORT
	, NODE
	, "TYPE"
	, "OPTIONS"
	, REMARK
	, ALIAS
	, DEFAULT_OPTION_VALUE
)
VALUES
(
	  ${MODULE}
	, ${DESCRIPTION}
	, ${PARENT}
	, ${SORT}
	, ${NODE}
	, ${TYPE}
	, ${OPTIONS}
	, ${REMARK}
	, ${ALIAS}
	, ${DEFAULT_OPTION_VALUE}
)
